from pathlib import Path
p=Path('smeny_pro_mobile_build/www/index.html'); s=p.read_text(encoding='utf-8')
def rep(a,b,n):
 global s
 if a not in s: raise SystemExit('Missing anchor: '+n)
 s=s.replace(a,b,1)
rep("settings:{org:'Moje organizace'}","settings:{org:'Moje organizace',workplace:'',address:'',contactEmail:'',contactPhone:'',team:'',absenceTypes:['Dovolená','Nemoc','Lékař','Osobní volno','Neplacené volno','Školení','Jiné'],holidays:[],holidayAsWeekend:false,notifyUnfilled:true,notifyPendingAbsences:true,defaultEmployeeRole:'Zaměstnanec',theme:'dark',accent:'#35b9c8',weekStart:1,breakMinutes:0,pinSalt:'',pinHash:''}",'defaults')
rep('<button data-page="reports"><span class="ico">▥</span>Statistiky a export</button></nav>','<button data-page="reports"><span class="ico">▥</span>Statistiky a export</button><button data-page="settings"><span class="ico">⚙</span>Nastavení ROSTERA</button></nav>','nav')
css='''\n.settings-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.settings-card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px;min-width:0}.settings-card h2{font-size:15px;margin:0 0 5px}.settings-card p{font-size:12px;color:var(--muted)}body.rostera-dark{--bg:#0c1422;--panel:#131f31;--ink:#e8eef8;--muted:#9aabc2;--line:#26364d;--nav:#080f1b;--blue2:#1a3448;--shadow:0 8px 28px #0003}body.rostera-dark .topbar,body.rostera-dark .day,body.rostera-dark .modal{background:#131f31;color:var(--ink)}body.rostera-dark .field input,body.rostera-dark .field select,body.rostera-dark .field textarea{background:#0e1929;color:var(--ink);border-color:var(--line)}body.rostera-dark th{background:#18263a;color:#aebbd0}#rosteraLock{position:fixed;inset:0;z-index:1000;background:#091321f5;display:none;align-items:center;justify-content:center;padding:22px}#rosteraLock.show{display:flex}#rosteraLock .lockbox{width:min(390px,100%);background:#142238;border:1px solid #2b405e;border-radius:18px;padding:26px;color:#eef5ff}#rosteraLock input{width:100%;padding:13px;border-radius:9px;background:#0c1728;color:white;margin:12px 0}@media(max-width:700px){.settings-grid{grid-template-columns:1fr}}\n'''
