rep("function save(){localStorage.setItem('smenypro_db',JSON.stringify(db))}","function save(){let payload=JSON.stringify(db);try{localStorage.setItem('rostera_auto_backup',JSON.stringify({savedAt:new Date().toISOString(),data:db}))}catch(e){}localStorage.setItem('smenypro_db',payload)}",'auto backup')
rep("function render(page='dashboard'){let v=$('#view');$('#crumb').textContent=({dashboard:'Přehled',schedule:'Rozpis směn',employees:'Zaměstnanci',positions:'Pracovní pozice',rules:'Pravidla a generátor',absences:'Absence a volno',reports:'Statistiky a exportg})[page];","function render(page='dashboard'){let v=$('#view');$('#crumb').textContent=({dashboard:'Přehled',schedule:'Rozpis směn',employees:'Zaměstnanci',positions:'Pracovní pozice',rules:'Pravidla a generátor',absences:'Absence a volno',reports:'Statistiky a export',settings:'Nastavení ROSTERA'})[page];",'route label')
rep("if(page==='reports')v.innerHTML=reportsPage();}","if(page==='reports')v.innerHTML=reportsPage();if(page==='settings')v.innerHTML=settingsPage();}",'route')
rep('<div class="avatar">A</div>','<button class="ghost" onclick="lockRosterApp()">Zámek</button><div class="avatar">R</div>','lock shortcut')
rep('<select name="type"><option>Dovolená</option><option>Nemoc</option><option>Lékař</option><option>Osobní volno</option><option>Neplacené volno</option><option>Školení</option><option>Jiné</option></select>','<select name="type">${(db.settings.absenceTypes||[\'Dovolená\',\'Nemoc\',\'Lékař\',\'Osobní volno\',\'Neplacené volno\',\'Školení\',\'Jiné\']).map(t=>`<option>${esc(t)}</option>`).join(\'\')}</select>','absence types')
rep('weekend=[0,6].includes(d.getDay()),targets=','weekend=[0,6].includes(d.getDay())||(db.settings.holidayAsWeekend&&(db.settings.holidays||[]).includes(ds)),targets=','holiday rules')
rep("db={...defaults,...x};save();render('dashboard');toast('Záloha úspěšně obnovena.')","db={...defaults,...x};db.rules={...defaults.rules,...(x.rules||{})};db.settings={...defaults.settings,...(x.settings||{})};save();render('dashboard');toast('Záloha úspěšně obnovena.')",'import migration')
js=r'''function settingsPage(){let s=db.settings,r=db.rules;let card=(n,t,body)=>`<section class="settings-card"><h2>${n}. ${t}</h2>${body}</section>`;let inp=(label,name,val,type='text')=>`<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(val??'')}"></div>`;let roles=db.employees.map(e=>`<div class="toolbar"><span>${esc(e.name)}</span><select onchange="setEmployeeRole('${e.id}',this.value)"><option ${e.appRole==='Vedoucí'?'selected':''}>Vedoucí</option><option ${!e.appRole||e.appRole==='Zaměstnanec'?'selected':''}>Zaměstnanec</option><option ${e.appRole==='Pouze čtení'?'selected':''}>Pouze čtení</option></select></div>`).join('')||'<p>Nejsou přidáni zaměstnanci.</p>';let hol=(s.holidays||[]).map((d,i)=>`<div class="toolbar">${esc(d)} <button class="danger" onclick="removeRosterHoliday(${i})">Odebrat</button></div>`).join('');return pageHead('Nastavení ROSTERA','Řídicí centrum aplikace')+`<div class="notice">Data se ukládají lokálně. Role jsou zatím evidenční, nejedná se o víceuživatelské účty. Push notifikace nejsou v offline verzi dostupné.</div><div class="settings-grid">${card(1,'Pracoviště a firma',`<form id="co" class="formgrid">${inp('Organizace','org',s.org)}${inp('Pracoviště','workplace',s.workplace)}${inp('Adresa','address',s.address)}${inp('E-mail','contactEmail',s.contactEmail,'email')}${inp('Telefon','contactPhone',s.contactPhone)}${inp('Tým / oddělení','team',s.team)}<button type="button" class="primary" onclick="saveCo()">Uložit</button></form>`)}${card(2,'Výchozí směny',`<form id="sh" class="formgrid">${inp('Denní od','dayStart',r.dayStart,'time')}${inp('Denní do','dayEnd',r.dayEnd,'time')}${inp('Noční od','nightStart',r.nightStart,'time')}${inp('Noční do','nightEnd',r.nightEnd,'time')}${inp('Přestávka (min.)','breakMinutes',s.breakMinutes,'number')}<button type="button" class="primary" onclick="saveSh()">Uložit časy</button></form><p>Přestávka je evidenční údaj, zatím se neodečítá z hodin.</p>`)}${card(3,'Pravidla plánování',`<form id="pl" class="formgrid">${inp('Max. směn za sebou','maxConsecutive',r.maxConsecutive,'number')}${inp('Min. odpočinek (h)','minRest',r.minRest,'number')}${inp('Max. hodin / měsíc','maxHours',r.maxHours,'number')}<label><input type="checkbox" name="avoidNightToDay" ${r.avoidNightToDay?'checked':''}> Zamezit noční → denní</label><label><input type="checkbox" name="preferFair" ${r.preferFair?'checked':''}> Rovnoměrné rozdělení</label><label><input type="checkbox" name="weekendCount" ${r.weekendCount?'checked':''}> Rovnoměrné víkendy</label><button type="button" class="primary" onclick="savePl()">Uložit pravidla</button></form>`)}${card(4,'Zaměstnanci a role',`<label>Výchozí role</label><select id="defRole"><option>Zaměstnanec</option><option>Vedoucí</option><option>Pouze čtení</option></select><button class="ghost" onclick="saveDefRole()">Uložit výchozí roli</button>${roles}<button class="ghost" onclick="nav('employees')">Správa zaměstnanců</button><p>Role jsou pouze organizační štítky, bez přístupových práv.</p>`)}${card(5,'Personální obsazení',`<form id="st" class="formgrid">${inp('Počet lidí – denní','dayCount',r.dayCount,'number')}${inp('Počet lidí – noční','nightCount',r.nightCount,'number')}${inp('Navíc Po–Pá','weekdayEx',r.weekdayEx,'number')}${inp('Navíc víkend','weekendEx',r.weekendEx,'number')}<label><input type="checkbox" name="includeLead" ${r.includeLead?'checked':''}> Vyžadovat vedoucího</label><button type="button" class="primary" onclick="saveSt()">Uložit obsazení</button></form>`)}${card(6,'Upozornění v aplikaci',`<label><input type="checkbox" id="nu" ${s.notifyUnfilled!==false?'checked':''}> Upozornění na neobsazená místa</label><label><input type="checkbox" id="np" ${s.notifyPendingAbsences!==false?'checked':''}> Upozornění na čekající absence</label><button class="primary" onclick="saveNotices()">Uložit upozornění</button><p>Volby jsou připravené pro upozornění v přehledu; push notifikace nejsou dostupné.</p>`)}${card(7,'Absence a svátky',`<label>Typy absencí – oddělit čárkou</label><textarea id="at" rows="3">${esc((s.absenceTypes||[]).join(', '))}</textarea><label><input type="checkbox" id="hw" ${s.holidayAsWeekend?'checked':''}> Svátky použít jako víkendové obsazení</label><button class="primary" onclick="saveAbs()">Uložit typy</button><label>Přidat mimořádný den</label><input type="date" id="hd"><button class="ghost" onclick="addHol()">Přidat</button>${hol}<p>Kalendář českých svátků se zatím neimportuje automaticky.</p>`)}${card(8,'Zálohování a data',`<button class="primary" onclick="exportJSON()">Export úplné zálohy JSON</button><button class="ghost" onclick="importJSON()">Import JSON</button><button class="ghost" onclick="restoreBackup()">Obnovit automatickou kopii</button><p>Automatická kopie se ukládá v tomto zařízení při každém uložení; není cloudová.</p>`)}${card(9,'Vzhled',`<label>Motiv</label><select id="th"><option value="dark" ${s.theme!=='light'?'selected':''}>Tmavý PRO</option><option value="light" ${s.theme==='light'?'selected':''}>Světlý</option></select><label>Akcentní barva</label><input type="color" id="ac" value="${s.accent||'#35b9c8'}"><label>Začátek týdne</label><select id="ws"><option value="1">Pondělí</option><option value="0">Neděle</option></select><button class="primary" onclick="saveTheme()">Použít vzhled</button>`)}${card(10,'Systém a zabezpečení',`<label>Nový PIN (4–12 číslic)</label><input id="pin" type="password" inputmode="numeric" maxlength="12"><label>Potvrzení PINu</label><input id="pin2" type="password" inputmode="numeric" maxlength="12"><button class="primary" onclick="setPin()">Nastavit PIN</button><button class="ghost" onclick="removePin()">Vypnout PIN</button><button class="ghost" onclick="lockRoster()">Zamknout nyní</button><button class="ghost" onclick="diagnostics()">Kontrola dat</button><p>PIN zamyká aplikaci na zařízení, nešifruje lokálně uložená data.</p>`)}</div>`}
function saveCo(){let f=$('#co');['org','workplace','address','contactEmail','contactPhone','team'].forEach(k=>db.settings[k]=f[k].value.trim());save();toast('Pracoviště uloženo')}
function saveSh(){let f=$('#sh');['dayStart','dayEnd','nightStart','nightEnd'].forEach(k=>db.rules[k]=f[k].value);db.settings.breakMinutes=+f.breakMinutes.value||0;save();toast('Časy směn uloženy')}
function savePl(){let f=$('#pl');['maxConsecutive','minRest','maxHours'].forEach(k=>db.rules[k]=+f[k].value);['avoidNightToDay','preferFair','weekendCount'].forEach(k=>db.rules[k]=f[k].checked);save();toast('Pravidla uložena')}
function saveSt(){let f=$('#st');['dayCount','nightCount','weekdayEx','weekendEx'].forEach(k=>db.rules[k]=+f[k].value);db.rules.includeLead=f.includeLead.checked;save();toast('Obsazení uloženo')}
function setEmployeeRole(id,v){let e=db.employees.find(x=>x.id===id);if(e){e.appRole=v;save()}}
function saveDefRole(){db.settings.defaultEmployeeRole=$('#defRole').value;save();toast('Výchozí role uložena')}
function saveNotices(){db.settings.notifyUnfilled=$('#nu').checked;db.settings.notifyPendingAbsences=$('#np').checked;save();toast('Upozornění uložena')}
function saveAbs(){let a=[...new Set($('#at').value.split(',').map(x=>x.trim()).filter(Boolean))];if(!a.length){toast('Zadej typ absence');return}db.settings.absenceTypes=a;db.settings.holidayAsWeekend=$('#hw').checked;save();toast('Absence uloženy')}
function addHol(){let d=$('#hd').value;if(!d)return toast('Vyber datum');if(!db.settings.holidays.includes(d))db.settings.holidays.push(d);save();render('settings')}
function removeRosterHoliday(i){db.settings.holidays.splice(i,1);save();render('settings')}
function saveTheme(){db.settings.theme=$('#th').value;db.settings.accent=$('#ac').value;db.settings.weekStart=+$('#ws').value;applyTheme();save();toast('Vzhled změněn')}
function applyTheme(){document.body.classList.toggle('rostera-dark',db.settings.theme!=='light');document.documentElement.style.setProperty('--blue',db.settings.accent||'#35b9c8')}
function restoreBackup(){try{let b=JSON.parse(localStorage.getItem('rostera_auto_backup')||'null');if(!b?.data||!confirm('Obnovit poslední automatickou kopii?'))return;db={...defaults,...b.data};db.rules={...defaults.rules,...(b.data.rules||{})};db.settings={...defaults.settings,...(b.data.settings||{})};save();render('dashboard');applyTheme();toast('Kopie obnovena')}catch(e){toast('Kopii nelze obnovit')}}
async function pinHash(pin,salt){let enc=new TextEncoder(),key=await crypto.subtle.importKey('raw',enc.encode(pin),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:enc.encode(salt),iterations:120000,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function setPin(){let a=$('#pin').value,b=$('#pin2').value;if(!/^\d{4,12}$/.test(a)||a!==b)return toast('PIN musí mít 4–12 shodných číslic');try{db.settings.pinSalt=uid()+uid()+Date.now();db.settings.pinHash=await pinHash(a,db.settings.pinSalt);save();$('#pin').value=$('#pin2').value='';toast('PIN nastaven')}catch(e){toast('Bezpečné uložení PINu není dostupné')}}
function removePin(){if(!confirm('Vypnout PIN?'))return;db.settings.pinSalt=db.settings.pinHash='';save();toast('PIN vypnut')}
function lockRoster(){if(!db.settings.pinHash)return toast('Nejprve nastav PIN');let el=$('#rosteraLock');if(!el){el=document.createElement('div');el.id='rosteraLock';el.innerHTML='<div class="lockbox"><h2>ROSTERA</h2><p>Zadej PIN</p><form id="unlockForm"><input id="unlockPin" type="password" inputmode="numeric" required><button class="primary">Odemknout</button><p id="unlockError"></p></form></div>';document.body.appendChild(el);$('#unlockForm').onsubmit=async ev=>{ev.preventDefault();if(await pinHash($('#unlockPin').value,db.settings.pinSalt)===db.settings.pinHash)el.classList.remove('show');else $('#unlockError').textContent='Nesprávný PIN'}}el.classList.add('show')}
function diagnostics(){let bad=db.assignments.filter(a=>!db.employees.some(e=>e.id===a.employeeId)).length;showModal('Kontrola dat',bad?`<div class="notice">${bad} směn odkazuje na neexistující zaměstnance.</div>`:'<div class="rulebox">Základní kontrola dat proběhla v pořádku.</div>',null,'<button class="primary" onclick="closeModal()">Zavřít</button>')}
'''
# Replace a unique marker at the final bootstrap only; do not inject into import handlers.
rep("\nrender('dashboard');\n</script>","\n"+js+"\nrender('dashboard');applyTheme();if(db.settings.pinHash)setTimeout(lockRoster,250);\n</script>",'settings code injection')
p.write_text(s,encoding='utf-8');print('ROSTERA settings installed')
